package com.jinloes.practice;
import java.util.Arrays;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: an integer array, for example: [1, 4, 9, 8, 3, 2, 6, 7]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) {runInput(String.join(" ",args).trim());return;} assertThat(Solution.sortAlternatingRuns(new int[]{1,4,9,8,3,2,6,7})).as("Example 1").containsExactly(1,2,3,4,6,7,8,9); assertThat(Solution.sortAlternatingRuns(new int[]{5,4,4,1})).as("Example 2").containsExactly(1,4,4,5); System.out.println("Examples passed: 2"); } private static void runInput(String input) {try{System.out.println(Arrays.toString(Solution.sortAlternatingRuns(parseArray(input))));}catch(RuntimeException e){System.out.println("Could not read \""+input+"\". "+USAGE);}} private static int[] parseArray(String text){String s=text.trim();if(!s.startsWith("[")||!s.endsWith("]"))throw new IllegalArgumentException("array");String b=s.substring(1,s.length()-1).trim();if(b.isEmpty())return new int[0];String[] parts=b.split(",");int[] a=new int[parts.length];for(int i=0;i<parts.length;i++)a[i]=Integer.parseInt(parts[i].trim());return a;} }

